// Double-submit CSRF token (Backend M2 hardening, slice 46).
// Exercises the real middleware through a small express app with
// cookie-parser, plus the real token-issue handler — not a copy of
// the logic. No database is connected here; tokens below are fresh
// random values generated by the middleware itself, never secrets.
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const express = require("express");
const axios = require("axios");
const cookieParser = require("cookie-parser");

const {
  CSRF_COOKIE_NAME,
  CSRF_HEADER_NAME,
  generateCsrfToken,
  issueCsrfToken,
  tokensEqual,
  csrfTokenCheck,
} = require("../middleware/csrfToken");

async function startApp(t) {
  const app = express();
  app.use(cookieParser());
  app.use(csrfTokenCheck);
  app.get("/csrf-token", issueCsrfToken);
  app.all("/ping", (_req, res) => res.json({ ok: true }));
  const server = await new Promise((resolve) => {
    const s = app.listen(0, "127.0.0.1", () => resolve(s));
  });
  t.after(() => server.close());
  return `http://127.0.0.1:${server.address().port}`;
}

async function request(base, method, headers, cookieHeader) {
  const res = await axios({
    method,
    url: `${base}/ping`,
    headers: { ...headers, ...(cookieHeader ? { Cookie: cookieHeader } : {}) },
    validateStatus: () => true,
  });
  return res;
}

test("generated tokens are 64 hex chars and differ", () => {
  const a = generateCsrfToken();
  const b = generateCsrfToken();
  assert.match(a, /^[0-9a-f]{64}$/);
  assert.match(b, /^[0-9a-f]{64}$/);
  assert.notEqual(a, b);
});

test("tokensEqual is a constant-time equality check, not a prefix match", () => {
  const token = generateCsrfToken();
  assert.equal(tokensEqual(token, token), true);
  assert.equal(tokensEqual(token, `${token}0`), false);
  assert.equal(tokensEqual(token, token.slice(0, -1)), false);
  assert.equal(tokensEqual(token, undefined), false);
  assert.equal(tokensEqual(undefined, token), false);
  assert.equal(tokensEqual("", ""), false);
});

test("issue handler returns a token and sets the same value as a cookie", async (t) => {
  const base = await startApp(t);
  const res = await axios.get(`${base}/csrf-token`, { validateStatus: () => true });
  assert.equal(res.status, 200);
  assert.match(res.data.csrfToken, /^[0-9a-f]{64}$/);
  const setCookie = res.headers["set-cookie"] || [];
  assert.ok(setCookie.length >= 1);
  const cookieValue = setCookie[0].split(";")[0].split("=")[1];
  assert.equal(cookieValue, res.data.csrfToken);
  assert.ok(setCookie[0].toLowerCase().includes("httponly"));
});

test("POST with matching header and cookie passes", async (t) => {
  const base = await startApp(t);
  const token = generateCsrfToken();
  const res = await request(
    base,
    "post",
    { [CSRF_HEADER_NAME]: token, Origin: "https://mentorai-prod.vercel.app" },
    `${CSRF_COOKIE_NAME}=${token}`,
  );
  assert.equal(res.status, 200);
});

test("POST with a mismatched header is rejected 403 with the CSRF code", async (t) => {
  const base = await startApp(t);
  const res = await request(
    base,
    "post",
    { [CSRF_HEADER_NAME]: generateCsrfToken(), Origin: "https://mentorai-prod.vercel.app" },
    `${CSRF_COOKIE_NAME}=${generateCsrfToken()}`,
  );
  assert.equal(res.status, 403);
  assert.equal(res.data.code, "CSRF_TOKEN_INVALID");
});

test("POST with a header but no cookie is rejected 403", async (t) => {
  const base = await startApp(t);
  const res = await request(
    base,
    "post",
    { [CSRF_HEADER_NAME]: generateCsrfToken(), Origin: "https://mentorai-prod.vercel.app" },
    undefined,
  );
  assert.equal(res.status, 403);
  assert.equal(res.data.code, "CSRF_TOKEN_INVALID");
});

test("POST with an auth cookie but no token is rejected 403 (the browser attack case)", async (t) => {
  const base = await startApp(t);
  const res = await request(
    base,
    "post",
    { Origin: "https://evil.vercel.app" },
    "token=some-jwt-value",
  );
  assert.equal(res.status, 403);
  assert.equal(res.data.code, "CSRF_TOKEN_INVALID");
});

test("POST with an Origin but no cookies and no token is rejected 403", async (t) => {
  const base = await startApp(t);
  const res = await request(
    base,
    "post",
    { Origin: "https://mentorai-prod.vercel.app" },
    undefined,
  );
  assert.equal(res.status, 403);
});

test("POST with no Origin, no Referer, and no cookies passes (non-browser passthrough)", async (t) => {
  const base = await startApp(t);
  const res = await request(base, "post", {}, undefined);
  assert.equal(res.status, 200);
});

test("GET is not state-changing, so a foreign Origin with no token passes", async (t) => {
  const base = await startApp(t);
  const res = await request(
    base,
    "get",
    { Origin: "https://evil.vercel.app" },
    "token=some-jwt-value",
  );
  assert.equal(res.status, 200);
});

test("PUT and DELETE with a mismatched token are rejected 403", async (t) => {
  const base = await startApp(t);
  for (const method of ["put", "delete"]) {
    const res = await request(
      base,
      method,
      { [CSRF_HEADER_NAME]: generateCsrfToken() },
      `${CSRF_COOKIE_NAME}=${generateCsrfToken()}`,
    );
    assert.equal(res.status, 403);
  }
});

test("server.js mounts csrfTokenCheck exactly once, after cookieParser, before the routes", () => {
  const src = fs.readFileSync(path.join(__dirname, "..", "server.js"), "utf8");
  const mounts = (src.match(/app\.use\(csrfTokenCheck\)/g) || []).length;
  assert.equal(mounts, 1);
  assert.ok(src.indexOf("app.use(cookieParser())") < src.indexOf("app.use(csrfTokenCheck)"));
  assert.ok(src.indexOf("app.use(csrfTokenCheck)") < src.indexOf("app.use('/api/auth'"));
});

test("auth router exposes GET /csrf-token and CORS allows the token header", () => {
  const authSrc = fs.readFileSync(path.join(__dirname, "..", "routes", "auth.js"), "utf8");
  assert.ok(authSrc.includes('router.get("/csrf-token", issueCsrfToken)'));
  const corsSrc = fs.readFileSync(path.join(__dirname, "..", "middleware", "cors.js"), "utf8");
  assert.ok(corsSrc.includes('"X-CSRF-Token"'));
});

test("client wires the token on both mutation transports", () => {
  const axiosSrc = fs.readFileSync(
    path.join(__dirname, "..", "..", "client", "src", "lib", "axios.ts"),
    "utf8",
  );
  assert.ok(axiosSrc.includes("export async function getCsrfToken"));
  assert.ok(axiosSrc.includes('CSRF_TOKEN_INVALID'));
  assert.ok(axiosSrc.includes("__csrfRetried"));
  const storeSrc = fs.readFileSync(
    path.join(__dirname, "..", "..", "client", "src", "store", "conversationStore.ts"),
    "utf8",
  );
  assert.ok(storeSrc.includes("getCsrfToken"));
  assert.ok(storeSrc.includes('"X-CSRF-Token"'));
  assert.ok(storeSrc.includes('probe?.code === "CSRF_TOKEN_INVALID"'));
});
